insert into public.bedaya_catalog(key,kind,payload,is_demo) values('rules-team-v1','rules','{"version":"2026-10-09","disclaimer":{"en":"Built from official Jordanian sources accessed on 2026-10-09. Fees can change; confirm with the office before paying.","ar":"مبنية على مصادر أردنية رسمية تم الاطلاع عليها في 2026-10-09. قد تتغير الرسوم؛ تأكد من الجهة قبل الدفع."},"provenance":{"repo":"https://github.com/Amin-Shahin-00/Beluga_HTU","branch":"M5_Ameen","commit":"00a3d0207222073c7812e2360afbd96f0337c1b7","verification":"team-supplied; not independently re-verified"},"steps":[{"order":1,"id":"reserve_trade_name","title":{"en":"Register a trade name","ar":"تسجيل الاسم التجاري"},"officeId":"MIT","requiredDocs":[{"docId":"national_id","condition":"always"}],"fee":{"minJod":20,"maxJod":30,"note":{"en":"20 JOD registration (+10 JOD if you ask for a name search first); 3 JOD per extra certificate copy","ar":"20 ديناراً للتسجيل (+10 دنانير إذا طلبت التحري عن الاسم أولاً)؛ 3 دنانير لكل نسخة إضافية من الشهادة"},"verified":"yes"},"days":{"value":0,"note":{"en":"Same visit as the trader registration","ar":"في نفس زيارة تسجيل التاجر"},"verified":"yes"},"condition":"optional","notes":{"en":"Only if you want a trade name for your business.","ar":"فقط إذا أردت اسماً تجارياً لمشروعك."},"sourceIds":["S4","S8"],"key":"reserve_trade_name","legalForm":"home_business"},{"order":2,"id":"register_sole_proprietorship","title":{"en":"Register as a trader (Commercial Registry)","ar":"التسجيل كتاجر (السجل التجاري)"},"officeId":"MIT","requiredDocs":[{"docId":"national_id","condition":"always"},{"docId":"service_booklet","condition":"if_male_born_1989_plus"}],"fee":{"minJod":15,"maxJod":45,"note":{"en":"5 JOD certificate + registration fee by capital: 10 JOD under 20,000 JOD, then 20 / 30 / 40 JOD; extra copies 3 JOD each","ar":"5 دنانير شهادة + رسم قيد حسب رأس المال: 10 دنانير لأقل من 20,000 دينار، ثم 20 / 30 / 40 ديناراً؛ النسخة الإضافية 3 دنانير"},"verified":"yes"},"days":{"value":0,"note":{"en":"Same day: about 15-75 minutes at MIT, paid in cash","ar":"في نفس اليوم: حوالي 15 إلى 75 دقيقة في الوزارة، والدفع نقداً"},"verified":"yes"},"condition":"always","notes":{"en":"Take a queue number at MIT in Abdali (outside Amman, the MIT directorate in your governorate) and fill in the trader declaration and pledge forms. Minimum declared capital is 1,000 JOD and no deposit is needed.","ar":"خذ رقم دور في الوزارة في العبدلي (وخارج عمّان مديرية الصناعة والتجارة في محافظتك) واملأ نموذجي تصريح احتراف التجارة والتعهد. الحد الأدنى لرأس المال المصرح به 1,000 دينار ولا يشترط إيداعه."},"sourceIds":["S1","S5","S8"],"key":"register_sole_proprietorship","legalForm":"home_business"},{"order":3,"id":"chamber_of_industry","title":{"en":"Join the Amman Chamber of Industry","ar":"الانتساب لغرفة صناعة عمّان"},"officeId":"ACI","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"lease_contract","condition":"if_rented"},{"docId":"property_ownership_document","condition":"always"},{"docId":"national_id","condition":"always"},{"docId":"trade_name_certificate","condition":"if_trade_name"}],"fee":{"minJod":40,"maxJod":175,"note":{"en":"Annual fee by capital (20 JOD under 10,000 JOD; 30 / 40 / 70 JOD above) + registration fee of 50% of the annual fee + community service fee (10 JOD under 10,000; 20 / 20 / 70 above). Under 10,000 JOD of capital it''s 40 JOD.","ar":"اشتراك سنوي حسب رأس المال (20 ديناراً لأقل من 10,000؛ 30 / 40 / 70 ديناراً لما فوق) + رسم تسجيل بنسبة 50% من الاشتراك السنوي + رسم خدمة مجتمع (10 دنانير لأقل من 10,000؛ 20 / 20 / 70 لما فوق). لرأس مال أقل من 10,000 دينار المجموع 40 ديناراً."},"verified":"yes"},"days":{"value":0,"note":{"en":"Same day: 5-15 minutes at the chamber''s office in the Ministry building","ar":"في نفس اليوم: 5 إلى 15 دقيقة في مكتب الغرفة داخل مبنى الوزارة"},"verified":"yes"},"condition":"if_food","notes":{"en":"Home food production counts as industry, so it''s the Chamber of Industry rather than the Chamber of Commerce.","ar":"يُعد تصنيع الغذاء المنزلي نشاطاً صناعياً، لذا الانتساب لغرفة الصناعة وليس غرفة التجارة."},"sourceIds":["S8"],"key":"chamber_of_industry","legalForm":"home_business"},{"order":4,"id":"gam_rental_certificate","title":{"en":"Get GAM''s rent-contract certificate","ar":"الحصول على شهادة عقد الإيجار من الأمانة"},"officeId":"GAM","requiredDocs":[{"docId":"lease_contract","condition":"always"},{"docId":"property_ownership_document","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":null,"maxJod":null,"note":{"en":"0.5% of the annual rent (max 15 JOD) + 0.3% of the total contract value in stamps","ar":"0.5% من الإيجار السنوي (بحد أقصى 15 ديناراً) + 0.003 من قيمة العقد الكلية طوابع"},"verified":"yes"},"days":{"value":0,"note":{"en":"Online, same day","ar":"إلكترونياً في نفس اليوم"},"verified":"yes"},"condition":"if_rented","notes":{"en":"Only if you rent the home.","ar":"فقط إذا كان المنزل مستأجراً."},"sourceIds":["S8"],"key":"gam_rental_certificate","legalForm":"home_business"},{"order":5,"id":"jfda_home_food_license","title":{"en":"Get JFDA food processing and label approval","ar":"الحصول على موافقة الغذاء والدواء على التصنيع والملصق"},"officeId":"JFDA","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"lease_contract","condition":"if_rented"},{"docId":"property_ownership_document","condition":"always"},{"docId":"building_documents","condition":"always"},{"docId":"building_residents_consent","condition":"always"},{"docId":"inspection_pledge","condition":"always"},{"docId":"product_label","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":200,"maxJod":null,"note":{"en":"100 JOD permit application + 10 JOD label approval per food type + 90 JOD lab tests per sample (30 physical, 30 microbiological, 30 chemical). For one food type: 200 JOD.","ar":"100 دينار طلب التصريح + 10 دنانير لاعتماد الملصق لكل نوع غذاء + 90 ديناراً فحوص مخبرية لكل عينة (30 فيزيائي، 30 ميكروبيولوجي، 30 كيميائي). لنوع غذاء واحد: 200 دينار."},"verified":"yes"},"days":{"value":10,"note":{"en":"7-10 days: the inspection visit comes 2-3 days after you apply, and the lab report 5-7 days after the samples","ar":"7 إلى 10 أيام: زيارة الكشف بعد 2 إلى 3 أيام من التقديم، وتقرير المختبر بعد 5 إلى 7 أيام من أخذ العينات"},"verified":"yes"},"condition":"if_food","notes":{"en":"Start the vocational licence request online at GAM first; you need its application number here. JFDA inspects your kitchen and takes samples.","ar":"ابدأ طلب رخصة المهن إلكترونياً لدى الأمانة أولاً لأنك تحتاج رقم الطلب هنا. تكشف المؤسسة على مطبخك وتأخذ عينات."},"sourceIds":["S6","S8"],"key":"jfda_home_food_license","legalForm":"home_business"},{"order":6,"id":"home_business_license","title":{"en":"Get the home-based vocational licence","ar":"الحصول على رخصة المهن المنزلية"},"officeId":"GAM","requiredDocs":[{"docId":"property_owner_approval","condition":"if_rented"},{"docId":"declaration_pledge","condition":"always"},{"docId":"registration_certificate","condition":"always"},{"docId":"property_ownership_document","condition":"always"},{"docId":"building_documents","condition":"always"},{"docId":"gam_rental_certificate","condition":"if_rented"},{"docId":"jfda_approval","condition":"if_food"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":20,"maxJod":50,"note":{"en":"20-50 JOD basic fee depending on the profession","ar":"20 إلى 50 ديناراً رسم أساسي حسب نوع المهنة"},"verified":"yes"},"days":{"value":3,"note":{"en":"3 working days once the file is complete; requested and issued online","ar":"3 أيام عمل بعد اكتمال الملف؛ الطلب والإصدار إلكترونيان"},"verified":"yes"},"condition":"always","notes":{"en":"GAM checks the home. You may use up to 15% of it (max 25 m²). Non-food activities may need chamber membership; GAM will tell you.","ar":"تكشف الأمانة على المنزل. يمكنك استخدام 15% منه كحد أقصى (25 متراً مربعاً). قد تحتاج المهن غير الغذائية الانتساب لغرفة، وستبلغك الأمانة بذلك."},"sourceIds":["S1","S2","S8"],"key":"home_business_license","legalForm":"home_business"},{"order":7,"id":"tax_number","title":{"en":"Get a tax number","ar":"الحصول على الرقم الضريبي"},"officeId":"ISTD","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"vocational_licence","condition":"always"},{"docId":"lease_contract","condition":"if_rented"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":0,"maxJod":0,"note":{"en":"Free","ar":"مجاناً"},"verified":"yes"},"days":{"value":0,"note":{"en":"Online, same day (up to 24 hours if you apply at the end of the working day); then have the certificate ratified at ISTD in about 5 minutes","ar":"إلكترونياً في نفس اليوم (حتى 24 ساعة إذا قدمت في نهاية الدوام)؛ ثم تصديق الشهادة لدى الدائرة في حوالي 5 دقائق"},"verified":"yes"},"condition":"always","notes":{"en":"Use the tax number on all your invoices.","ar":"استخدم الرقم الضريبي في كل فواتيرك."},"sourceIds":["S1","S7","S12"],"key":"tax_number","legalForm":"home_business"},{"order":8,"id":"business_seal","title":{"en":"Make a business stamp","ar":"عمل ختم للمنشأة"},"officeId":"SEAL","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":10,"maxJod":20,"note":{"en":"10-20 JOD at any seal shop","ar":"10 إلى 20 ديناراً في أي محل أختام"},"verified":"yes"},"days":{"value":0,"note":{"en":"Same day","ar":"في نفس اليوم"},"verified":"yes"},"condition":"always","notes":{"en":"You need the stamp to activate your social security account.","ar":"تحتاج الختم لتفعيل حساب الضمان الاجتماعي."},"sourceIds":["S11"],"key":"business_seal","legalForm":"home_business"},{"order":9,"id":"social_security","title":{"en":"Register with social security","ar":"التسجيل في الضمان الاجتماعي"},"officeId":"SSC","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"vocational_licence","condition":"always"},{"docId":"liaison_officer_form","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":0,"maxJod":0,"note":{"en":"No registration fee; monthly contributions on wages","ar":"لا رسوم تسجيل؛ تُدفع اشتراكات شهرية على الأجور"},"verified":"yes"},"days":{"value":2,"note":{"en":"1-2 days: get the number online, then activate the account at SSC","ar":"1 إلى 2 يوم: الحصول على الرقم إلكترونياً ثم تفعيل الحساب لدى المؤسسة"},"verified":"yes"},"condition":"always","notes":{"en":"Mandatory for the owner of a sole proprietorship who works in it, and for every employee.","ar":"إلزامي لمالك المؤسسة الفردية الذي يعمل فيها ولكل موظف."},"sourceIds":["S1","S11"],"key":"social_security","legalForm":"home_business"},{"order":1,"id":"reserve_trade_name","title":{"en":"Register a trade name","ar":"تسجيل الاسم التجاري"},"officeId":"MIT","requiredDocs":[{"docId":"national_id","condition":"always"}],"fee":{"minJod":20,"maxJod":30,"note":{"en":"20 JOD registration (+10 JOD if you ask for a name search first); 3 JOD per extra certificate copy","ar":"20 ديناراً للتسجيل (+10 دنانير إذا طلبت التحري عن الاسم أولاً)؛ 3 دنانير لكل نسخة إضافية من الشهادة"},"verified":"yes"},"days":{"value":0,"note":{"en":"Same visit as the trader registration","ar":"في نفس زيارة تسجيل التاجر"},"verified":"yes"},"condition":"optional","notes":{"en":"Only if you want a trade name for your business.","ar":"فقط إذا أردت اسماً تجارياً لمشروعك."},"sourceIds":["S4","S9"],"key":"reserve_trade_name","legalForm":"sole_proprietorship"},{"order":2,"id":"register_sole_proprietorship","title":{"en":"Register as a trader (Commercial Registry)","ar":"التسجيل كتاجر (السجل التجاري)"},"officeId":"MIT","requiredDocs":[{"docId":"national_id","condition":"always"},{"docId":"service_booklet","condition":"if_male_born_1989_plus"}],"fee":{"minJod":15,"maxJod":45,"note":{"en":"5 JOD certificate + registration fee by capital: 10 JOD under 20,000 JOD, then 20 / 30 / 40 JOD; extra copies 3 JOD each","ar":"5 دنانير شهادة + رسم قيد حسب رأس المال: 10 دنانير لأقل من 20,000 دينار، ثم 20 / 30 / 40 ديناراً؛ النسخة الإضافية 3 دنانير"},"verified":"yes"},"days":{"value":0,"note":{"en":"Same day: about 15-75 minutes at MIT, paid in cash","ar":"في نفس اليوم: حوالي 15 إلى 75 دقيقة في الوزارة، والدفع نقداً"},"verified":"yes"},"condition":"always","notes":{"en":"Take a queue number at MIT in Abdali (outside Amman, the MIT directorate in your governorate). Minimum declared capital is 1,000 JOD and no deposit is needed.","ar":"خذ رقم دور في الوزارة في العبدلي (وخارج عمّان مديرية الصناعة والتجارة في محافظتك). الحد الأدنى لرأس المال المصرح به 1,000 دينار ولا يشترط إيداعه."},"sourceIds":["S1","S5","S9"],"key":"register_sole_proprietorship","legalForm":"sole_proprietorship"},{"order":3,"id":"chamber_membership","title":{"en":"Join the Amman Chamber of Commerce","ar":"الانتساب لغرفة تجارة عمّان"},"officeId":"ACC","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"trade_name_certificate","condition":"if_trade_name"},{"docId":"lease_contract","condition":"if_rented"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":30,"maxJod":2250,"note":{"en":"First registration by capital: 30 JOD under 5,000; 75 JOD for 5,000-50,000; 150 JOD for 50,000-100,000; up to 2,250 JOD (annual fee afterwards from 20 JOD)","ar":"التسجيل لأول مرة حسب رأس المال: 30 ديناراً لأقل من 5,000؛ 75 ديناراً من 5,000 إلى 50,000؛ 150 ديناراً من 50,000 إلى 100,000؛ حتى 2,250 ديناراً (والاشتراك السنوي بعدها من 20 ديناراً)"},"verified":"yes"},"days":{"value":0,"note":{"en":"Same day: 10-20 minutes at the chamber''s office in the Ministry building","ar":"في نفس اليوم: 10 إلى 20 دقيقة في مكتب الغرفة داخل مبنى الوزارة"},"verified":"yes"},"condition":"always","notes":{"en":"For businesses inside Greater Amman and the capital governorate.","ar":"للمنشآت ضمن حدود أمانة عمّان ومحافظة العاصمة."},"sourceIds":["S3","S9"],"key":"chamber_membership","legalForm":"sole_proprietorship"},{"order":4,"id":"gam_rental_certificate","title":{"en":"Get GAM''s rent-contract certificate","ar":"الحصول على شهادة عقد الإيجار من الأمانة"},"officeId":"GAM","requiredDocs":[{"docId":"lease_contract","condition":"always"},{"docId":"property_ownership_document","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":null,"maxJod":null,"note":{"en":"0.5% of the annual rent (max 15 JOD) + 0.3% of the total contract value in stamps","ar":"0.5% من الإيجار السنوي (بحد أقصى 15 ديناراً) + 0.003 من قيمة العقد الكلية طوابع"},"verified":"yes"},"days":{"value":0,"note":{"en":"Online, same day","ar":"إلكترونياً في نفس اليوم"},"verified":"yes"},"condition":"if_rented","notes":{"en":"Only if you rent the premises.","ar":"فقط إذا كان الموقع مستأجراً."},"sourceIds":["S9"],"key":"gam_rental_certificate","legalForm":"sole_proprietorship"},{"order":5,"id":"vocational_license","title":{"en":"Get the vocational licence for your shop or office","ar":"الحصول على رخصة المهن للمحل أو المكتب"},"officeId":"GAM","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"chamber_certificate","condition":"always"},{"docId":"gam_rental_certificate","condition":"if_rented"},{"docId":"property_ownership_document","condition":"always"},{"docId":"building_documents","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":3,"maxJod":1000,"note":{"en":"Depends on the activity: fixed-fee activities 25-200 JOD for individual traders (3-1,000 JOD for companies); capital-based activities 40-750 JOD. Plus 15 JOD per m² of signboard (min 1 m²) and an extra 20% of the licence fee (min 20 JOD).","ar":"حسب النشاط: الأنشطة ذات الرسم الثابت 25 إلى 200 دينار للتاجر الفرد (3 إلى 1,000 دينار للشركات)؛ والأنشطة حسب رأس المال 40 إلى 750 ديناراً. إضافة إلى 15 ديناراً لكل متر مربع من اللوحة الإعلانية (بحد أدنى متر واحد) و20% من رسم الرخصة (بحد أدنى 20 ديناراً)."},"verified":"yes"},"days":{"value":0,"note":{"en":"Online, same day once the documents are complete","ar":"إلكترونياً في نفس اليوم بعد اكتمال الوثائق"},"verified":"yes"},"condition":"always","notes":{"en":"Some activities need prior approval from a sector authority.","ar":"تحتاج بعض الأنشطة موافقة مسبقة من الجهة القطاعية المختصة."},"sourceIds":["S1","S9","S10"],"key":"vocational_license","legalForm":"sole_proprietorship"},{"order":6,"id":"tax_number","title":{"en":"Get a tax number","ar":"الحصول على الرقم الضريبي"},"officeId":"ISTD","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"vocational_licence","condition":"always"},{"docId":"lease_contract","condition":"if_rented"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":0,"maxJod":0,"note":{"en":"Free","ar":"مجاناً"},"verified":"yes"},"days":{"value":0,"note":{"en":"Online, same day (up to 24 hours if you apply at the end of the working day); then have the certificate ratified at ISTD in about 5 minutes","ar":"إلكترونياً في نفس اليوم (حتى 24 ساعة إذا قدمت في نهاية الدوام)؛ ثم تصديق الشهادة لدى الدائرة في حوالي 5 دقائق"},"verified":"yes"},"condition":"always","notes":{"en":"Use the tax number on all your invoices.","ar":"استخدم الرقم الضريبي في كل فواتيرك."},"sourceIds":["S1","S7","S12"],"key":"tax_number","legalForm":"sole_proprietorship"},{"order":7,"id":"business_seal","title":{"en":"Make a business stamp","ar":"عمل ختم للمنشأة"},"officeId":"SEAL","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":10,"maxJod":20,"note":{"en":"10-20 JOD at any seal shop","ar":"10 إلى 20 ديناراً في أي محل أختام"},"verified":"yes"},"days":{"value":0,"note":{"en":"Same day","ar":"في نفس اليوم"},"verified":"yes"},"condition":"always","notes":{"en":"You need the stamp to activate your social security account.","ar":"تحتاج الختم لتفعيل حساب الضمان الاجتماعي."},"sourceIds":["S11"],"key":"business_seal","legalForm":"sole_proprietorship"},{"order":8,"id":"social_security","title":{"en":"Register with social security","ar":"التسجيل في الضمان الاجتماعي"},"officeId":"SSC","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"vocational_licence","condition":"always"},{"docId":"liaison_officer_form","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":0,"maxJod":0,"note":{"en":"No registration fee; monthly contributions on wages","ar":"لا رسوم تسجيل؛ تُدفع اشتراكات شهرية على الأجور"},"verified":"yes"},"days":{"value":2,"note":{"en":"1-2 days: get the number online, then activate the account at SSC","ar":"1 إلى 2 يوم: الحصول على الرقم إلكترونياً ثم تفعيل الحساب لدى المؤسسة"},"verified":"yes"},"condition":"always","notes":{"en":"Mandatory for the owner of a sole proprietorship who works in it, and for every employee.","ar":"إلزامي لمالك المؤسسة الفردية الذي يعمل فيها ولكل موظف."},"sourceIds":["S1","S11"],"key":"social_security","legalForm":"sole_proprietorship"},{"order":1,"id":"register_llc","title":{"en":"Register the limited liability company","ar":"تسجيل الشركة ذات المسؤولية المحدودة"},"officeId":"CCD","requiredDocs":[{"docId":"national_id","condition":"always"},{"docId":"memorandum_of_association","condition":"always"},{"docId":"bank_capital_letter","condition":"always"}],"fee":{"minJod":310,"maxJod":null,"note":{"en":"Registration fee of 0.2% of capital (minimum 250 JOD) + 0.3% of capital in stamps + 10 JOD memorandum + 10 JOD per document + 15 JOD publishing + 10 JOD certificate + 5 JOD memorandum copy + 10 JOD company commercial registry. Plus the bank''s capital-deposit fee (about 50 JOD; varies by bank).","ar":"رسم تسجيل 0.002 من رأس المال (بحد أدنى 250 ديناراً) + 0.003 من رأس المال طوابع + 10 دنانير عقد التأسيس + 10 دنانير لكل وثيقة + 15 ديناراً نشر + 10 دنانير شهادة + 5 دنانير نسخة عقد التأسيس + 10 دنانير سجل تجاري للشركة. إضافة إلى عمولة البنك على إيداع رأس المال (حوالي 50 ديناراً وتختلف حسب البنك)."},"verified":"yes"},"days":{"value":2,"note":{"en":"1-2 days, mostly online","ar":"1 إلى 2 يوم، ومعظمها إلكتروني"},"verified":"yes"},"condition":"always","notes":{"en":"Minimum capital is 1 JOD. T